(function(){
  CardSpoke_MODS.register('quick-palette', {
    meta: {
      name: 'Quick Palette',
      type: 'Plugin',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Adds a floating accent switcher with three curated palettes',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onAppInit(ctx){
      const palettes = [
        { name: 'Sunset', accent: '#f97316' },
        { name: 'Lagoon', accent: '#10b981' },
        { name: 'Lumen', accent: '#a855f7' }
      ];
      const tray = document.createElement('div');
      tray.className = 'qp-tray';
      palettes.forEach(p => {
        const btn = document.createElement('button');
        btn.className = 'qp-dot';
        btn.style.setProperty('--qp-accent', p.accent);
        btn.title = 'Switch accent to ' + p.name;
        btn.onclick = () => {
          document.documentElement.style.setProperty('--accent', p.accent);
          ctx.api.showToast('Accent set to ' + p.name, 'info');
        };
        tray.appendChild(btn);
      });
      document.body.appendChild(tray);
    },
    onDisable(){
      const tray = document.querySelector('.qp-tray');
      if(tray) tray.remove();
    }
  });
})();

css:
.qp-tray { position: fixed; bottom: 18px; right: 18px; display: flex; gap: 10px; padding: 10px 12px; border-radius: 999px; background: color-mix(in srgb, var(--bg, #0b1021) 70%, var(--bg-surface, #0f162b) 30%); box-shadow: 0 12px 28px rgba(0,0,0,0.25); z-index: 99; }
.qp-dot { width: 16px; height: 16px; border-radius: 50%; border: 2px solid rgba(255,255,255,0.8); background: var(--qp-accent); cursor: pointer; box-shadow: inset 0 0 0 2px rgba(0,0,0,0.12); }
.qp-dot:focus-visible { outline: 2px solid var(--qp-accent); outline-offset: 3px; }
